customMethods.script:
system.perspective.print("deleteAttribute() called ")

for row in self.view.custom.table.selection.data:
	retVal = system.kanoa.quality.config.deleteAttributeWithHistory(row['attributeId'], self.view.custom.security.userId)

	if retVal: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Attribute deleted'})
	else: system.perspective.sendMessage('showFailerToast', {'message': 'Attribute could not be deleted'})

self.view.refreshBinding("custom.filter.data")	 #Update the Tree Selector
self.view.refreshBinding("custom.table.data")

return

transforms.code:

security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['configureQuality']['enabled']: 
		canCreate = True
		canEdit = True if len(value['data'] or []) > 0 else False

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}
